import pandas as pd

def find_categories(members: pd.DataFrame, visits: pd.DataFrame, purchases: pd.DataFrame) -> pd.DataFrame:
    merged = pd.merge(members, visits, on='member_id', how='left')
    merged = pd.merge(merged, purchases, on='visit_id', how='left')

    rows = []
    for (mid, name), group in merged.groupby(['member_id', 'name']):
        total_visits = group['visit_id'].dropna().nunique()
        if total_visits == 0:
            cat = 'Bronze'
        else:
            purchases_count = group['charged_amount'].dropna().count()
            rate = (purchases_count * 100.0) / total_visits
            if rate >= 80:
                cat = 'Diamond'
            elif rate >= 50:
                cat = 'Gold'
            else:
                cat = 'Silver'
        rows.append({'member_id': mid, 'name': name, 'category': cat})
    return pd.DataFrame(rows)
